SELECT \"nct\", \"author\", \"year\", \"pubmed_id\" FROM public.\"clinical_trials\" WHERE (\"class_of_ici\" = 'PD1' OR \"class_of_ici_1\" = 'PD1') AND (\"name_of_ici\" ILIKE '%Pembrolizumab%' OR \"name_of_ici_1\" ILIKE '%Pembrolizumab%') AND \"year\" >= 2018 AND \"cancer_type\" = 'Renal cell carcinoma' AND (\"class_of_ici\" = 'CTLA-4' OR \"class_of_ici_1\" = 'CTLA-4') AND (\"name_of_ici\" ILIKE '%Ipilimumab%' OR \"name_of_ici_1\" ILIKE '%Ipilimumab%');